class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        maxVal = max(nums)
        count = 0
        left = 0
        res = 0

        for val in nums:
            if val == maxVal:
                count += 1
                if count >= k:
                    while nums[left] == maxVal:
                        count -= 1
                        left += 1
                    res += left
            else:
                res += left

        return res
